  1→@import "tailwindcss";
  2→
  3→/**
  4→ * GOLDEN RATIO DESIGN SYSTEM
  5→ *
  6→ * Spacing follows Fibonacci sequence (approximates φ = 1.618):
  7→ * - 21, 34, 55, 89, 144, 233px
  8→ * - Each value × 1.618 ≈ next value
  9→ *
 10→ * Blends production warmth with Pentagram refinement:
 11→ * - Dark theme with warm amber accent
 12→ * - Golden ratio spacing throughout
 13→ * - Editorial typography with warmth
 14→ * - Refined interactions
 15→ */
 16→
 17→:root {
 18→  /* Golden Ratio: φ = 1.618, 1/φ = 0.618 */
 19→  --phi: 1.618;
 20→  --phi-inverse: 0.618;
 21→
 22→  /* Fibonacci spacing scale (each × φ ≈ next) */
 23→  --space-xs: 21px;    /* Fibonacci */
 24→  --space-sm: 34px;    /* 21 × 1.618 ≈ 34 */
 25→  --space-md: 55px;    /* 34 × 1.618 ≈ 55 */
 26→  --space-lg: 89px;    /* 55 × 1.618 ≈ 89 */
 27→  --space-xl: 144px;   /* 89 × 1.618 ≈ 144 */
 28→  --space-2xl: 233px;  /* 144 × 1.618 ≈ 233 */
 29→  --space-section: 120px; /* Editorial section gap */
 30→
 31→  /* Typography - Helvetica Neue alternative */
 32→  /* Inter: neo-grotesque sans-serif, clean, neutral, screen-optimized */
 33→  --font-display: var(--font-inter), 'Inter', sans-serif;
 34→  --font-body: var(--font-inter), 'Inter', sans-serif;
 35→
 36→  /* Color palette - Dark with warm accent */
 37→  --background: #141414;
 38→  --foreground: #b8b8b8;
 39→  --text-primary: #e8e8e8;
 40→  --text-secondary: #8a8a8a;  /* Consolidated from #888888, #8a8a8a */
 41→  --text-muted: #6a6a6a;      /* Consolidated from #666666, #6a6a6a */
 42→  --text-dim: #5a5a5a;        /* NEW: For subtle labels, tags */
 43→  --border: #2a2a2a;
 44→  --border-subtle: #222222;   /* NEW: For subtle dividers */
 45→  --surface: #1a1a1a;         /* NEW: Elevated surface (cards, tags) */
 46→  --accent: #d4a853;          /* Warm gold - refined amber */
 47→  --accent-subtle: rgba(212, 168, 83, 0.15);
 48→
 49→  /* ═══════════════════════════════════════════════════════════════
 50→     COLOR HIERARCHY MANTRA
 51→     Information hierarchy = Color hierarchy
 52→
 53→     PRIMARY:   --text-primary (#e8e8e8) — Titles, headings, anchors
 54→     SECONDARY: --grey-500 (#7a7a7a)     — Descriptions, body content
 55→     TERTIARY:  --text-dim (#5a5a5a)     — Metadata, labels, footnotes
 56→
 57→     Rule: Brighter = more important. Dimmer = supporting context.
 58→     ═══════════════════════════════════════════════════════════════ */
 59→
 60→  /* Grey scale - Deterministic (use these, not hex values) */
 61→  --grey-50: #f0f0f0;   /* Brightest text */
 62→  --grey-100: #e8e8e8;  /* Primary text (= --text-primary) — TITLES */
 63→  --grey-200: #c0c0c0;  /* Emphasis text */
 64→  --grey-300: #a0a0a0;  /* Light secondary */
 65→  --grey-400: #8a8a8a;  /* Secondary text (= --text-secondary) */
 66→  --grey-500: #7a7a7a;  /* Medium grey — DESCRIPTIONS */
 67→  --grey-600: #6a6a6a;  /* Muted text (= --text-muted) */
 68→  --grey-700: #5a5a5a;  /* Dim text (= --text-dim) — METADATA */
 69→  --grey-800: #3a3a3a;  /* Separator dots */
 70→  --grey-900: #2a2a2a;  /* Borders (= --border) */
 71→
 72→  /* Micro spacing - for elements smaller than Fibonacci scale */
 73→  --space-micro: 4px;   /* Padding inside small elements */
 74→  --space-tiny: 8px;    /* Small gaps */
 75→  --space-small: 13px;  /* 21 / phi ≈ 13 */
 76→
 77→  /* Border radius scale - 3 values only */
 78→  --radius-sm: 4px;     /* Tags, buttons, code blocks */
 79→  --radius-md: 6px;     /* Thumbnails, cards */
 80→  --radius-full: 50%;   /* Circles, avatars */
 81→
 82→  /* Standardized transitions */
 83→  --transition-fast: 200ms ease-out;
 84→  --transition-base: 300ms ease-out;
 85→  --transition-smooth: 400ms cubic-bezier(0.25, 0.1, 0.25, 1);
 86→
 87→  /* Standardized hover opacity */
 88→  --hover-dim: 0.6;
 89→}
 90→
 91→@theme inline {
 92→  --color-background: var(--background);
 93→  --color-foreground: var(--foreground);
 94→  --font-sans: var(--font-inter);
 95→
 96→  /* Golden ratio spacing */
 97→  --spacing-section: var(--space-lg);  /* 89px */
 98→  --spacing-gutter: var(--space-md);   /* 55px */
 99→
100→  /* Layout - balanced width */
101→  --max-content-width: 1600px;
102→  --side-padding: clamp(24px, 3vw, 80px);     /* Fluid: scales with viewport */
103→  --side-padding-md: clamp(34px, 4vw, 100px);  /* Fluid: scales with viewport */
104→}
105→
106→/* Typography */
107→body {
108→  background: var(--background);
109→  color: var(--foreground);
110→  font-family: var(--font-body), -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
111→  font-feature-settings: "kern" 1, "liga" 1, "calt" 1;
112→  -webkit-font-smoothing: antialiased;
113→  -moz-osx-font-smoothing: grayscale;
114→}
115→
116→h1, h2, h3, h4, h5, h6, p {
117→  margin: 0;
118→  font-weight: 400;
119→}
120→
121→h1, h2, h3 {
122→  text-wrap: balance;
123→}
124→
125→button {
126→  border: none;
127→  font: inherit;
128→  cursor: pointer;
129→}
130→
131→html {
132→  scroll-behavior: smooth;
133→  background-color: var(--background);
134→}
135→
136→/* ===========================================
137→   PROJECT CARD INTERACTIONS
138→   =========================================== */
139→
140→/* Hover overlay and transitions handled inline in ProjectCard.tsx and VideoThumbnail.tsx */
141→/* This keeps all visual logic colocated with the component for easier maintenance */
142→
143→/* ===========================================
144→   NAVIGATION INTERACTIONS
145→   =========================================== */
146→
147→.nav-link {
148→  position: relative;
149→  display: inline-block;
150→  text-decoration: none;
151→  /* Reversed hover: full opacity by default, dims on hover */
152→  opacity: 1;
153→  transition: opacity var(--transition-smooth);
154→}
155→
156→@media (hover: hover) and (pointer: fine) {
157→  .nav-link:hover {
158→    opacity: var(--hover-dim);
159→  }
160→}
161→
162→/* Section headers - Light table effect */
163→.section-header-highlight {
164→  position: relative;
165→  display: inline-block;
166→  /* Light table: dimmed by default, reveals on hover */
167→  opacity: 0.5;
168→  transition: opacity var(--transition-smooth);
169→}
170→
171→@media (hover: hover) and (pointer: fine) {
172→  .section-header-highlight:hover {
173→    opacity: 1;
174→  }
175→}
176→
177→.nav-item-shift {
178→  transition: opacity var(--transition-smooth);
179→}
180→
181→/* Button arrow */
182→.button-arrow-shift {
183→  display: inline-flex;
184→  align-items: center;
185→  gap: var(--space-tiny);
186→}
187→
188→.button-arrow {
189→  transition: transform var(--transition-smooth), opacity var(--transition-smooth);
190→  opacity: 0.5;
191→}
192→
193→@media (hover: hover) and (pointer: fine) {
194→  .button-arrow-shift:hover .button-arrow {
195→    transform: translateX(4px);
196→    opacity: 1;
197→  }
198→}
199→
200→.gpu-accelerated {
201→  will-change: transform;
202→  transform: translateZ(0);
203→  backface-visibility: hidden;
204→}
205→
206→/* Vimeo iframe: force dark background before video loads (prevents white flash) */
207→iframe[src*="vimeo"],
208→iframe[src*="player.vimeo"] {
209→  background-color: #141414;
210→  border: none;
211→  display: block;
212→}
213→
214→/* ===========================================
215→   RELATED WORK THUMBNAILS
216→   =========================================== */
217→
218→.related-thumbnail img {
219→  transition: opacity 0.3s ease, transform 0.3s ease;
220→}
221→
222→.group:hover .related-thumbnail img {
223→  opacity: 1 !important;
224→  transform: scale(1.02);
225→}
226→
227→/* ===========================================
228→   ENTRANCE ANIMATIONS
229→   =========================================== */
230→
231→@keyframes fadeUp {
232→  from {
233→    opacity: 0;
234→    transform: translateY(21px);  /* Fibonacci */
235→  }
236→  to {
237→    opacity: 1;
238→    transform: translateY(0);
239→  }
240→}
241→
242→.project-card {
243→  opacity: 0;
244→  animation: fadeUp 0.7s ease-out forwards;
245→}
246→
247→.project-card:nth-child(1) { animation-delay: 0ms; }
248→.project-card:nth-child(2) { animation-delay: 80ms; }
249→.project-card:nth-child(3) { animation-delay: 160ms; }
250→.project-card:nth-child(4) { animation-delay: 240ms; }
251→.project-card:nth-child(5) { animation-delay: 320ms; }
252→.project-card:nth-child(6) { animation-delay: 400ms; }
253→
254→@keyframes fadeIn {
255→  from { opacity: 0; }
256→  to { opacity: 1; }
257→}
258→
259→.client-strip {
260→  animation: fadeIn 0.8s ease-out forwards;
261→  animation-delay: 200ms;
262→  opacity: 0;
263→}
264→
265→/* Scroll indicator */
266→@keyframes scrollFloat {
267→  0%, 100% {
268→    transform: translateY(0);
269→    opacity: 0.5;
270→  }
271→  50% {
272→    transform: translateY(6px);
273→    opacity: 0.8;
274→  }
275→}
276→
277→.scroll-chevron {
278→  animation: scrollFloat 2.8s ease-in-out infinite;
279→  will-change: transform, opacity;
280→}
281→
282→/* Availability indicator */
283→@keyframes availabilityPulse {
284→  0%, 100% { opacity: 0.6; }
285→  50% { opacity: 1; }
286→}
287→
288→.availability-dot {
289→  animation: availabilityPulse 2.5s ease-in-out infinite;
290→}
291→
292→/* Chat typing indicator */
293→@keyframes typingPulse {
294→  0%, 100% {
295→    opacity: 0.3;
296→    transform: scale(1);
297→  }
298→  50% {
299→    opacity: 1;
300→    transform: scale(1.15);
301→  }
302→}
303→
304→.typing-dot {
305→  will-change: transform, opacity;
306→}
307→
308→/* Chat message entrance */
309→@keyframes chatMessageIn {
310→  from {
311→    opacity: 0;
312→    transform: translateY(13px);  /* --space-small: 21 / phi */
313→  }
314→  to {
315→    opacity: 1;
316→    transform: translateY(0);
317→  }
318→}
319→
320→.chat-message-enter {
321→  animation: chatMessageIn 0.3s ease-out forwards;
322→}
323→
324→/* Reduced motion */
325→@media (prefers-reduced-motion: reduce) {
326→  html {
327→    scroll-behavior: auto;
328→  }
329→
330→  *,
331→  *::before,
332→  *::after {
333→    animation-duration: 0.01ms !important;
334→    animation-iteration-count: 1 !important;
335→    transition-duration: 0.01ms !important;
336→  }
337→
338→  [aria-live="polite"] {
339→    transition: none !important;
340→  }
341→
342→  .nav-link,
343→  .project-title h3,
344→  .section-header-highlight,
345→  .project-card,
346→  .nav-item-shift,
347→  .button-arrow,
348→  .scroll-chevron,
349→  .typing-dot,
350→  .chat-message-enter {
351→    transition: none !important;
352→    transform: none !important;
353→    animation: none !important;
354→  }
355→}
356→
357→/* ===========================================
358→   FOCUS INDICATORS FOR ACCESSIBILITY
359→   =========================================== */
